#include <iostream>
#include <algorithm>
#include <vector>
using namespace std;

#define int long long
const int MODX1 = 998244353, MODX2 = 1000000007;
const int powx[] = {1, 10, 100, 1000, 10000, 100000, 1000000};

int prefixSum[7], totalAnswer, counterX1, maxNumber, counterX2;
vector<int> digitLists[7];

void generateSequences(int level, int val) {
    if (level == 7) return;
    digitLists[level].push_back((counterX1 - val + MODX1) % MODX1);
    prefixSum[level] += (counterX1 - val + MODX1) % MODX1;
    counterX1++;
    for (int d = 0; d <= 9; ++d) {
        generateSequences(level + 1, val * 10 + d);
    }
}

bool inValidRange(int x) {
    return x * powx[6] + 999999 <= maxNumber && x * powx[6] * 10 > maxNumber;
}

void traverse(int level, int current) {
    if (current > maxNumber) return;
    if (inValidRange(current)) {
        for (int i = 0; i <= 6; ++i) {
            int p = ((counterX2 + 1 - (current * powx[i])) % MODX1 + MODX1) % MODX1;
            int pos = (int)(lower_bound(digitLists[i].begin(), digitLists[i].end(), MODX1 - p) - digitLists[i].begin());
            totalAnswer = (totalAnswer + (prefixSum[i] + p * digitLists[i].size() - MODX1 * (digitLists[i].size() - pos))) % MODX2;
        }
        counterX2 += counterX1;
        return;
    }
    counterX2++;
    totalAnswer = (totalAnswer + ((counterX2 - current) % MODX1 + MODX1) % MODX1) % MODX2;
    for (int d = (level == 0 ? 1 : 0); d <= 9; ++d) {
        traverse(level + 1, current * 10 + d);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> maxNumber;
    generateSequences(0, 0);
    for (int i = 0; i <= 6; ++i) {
        sort(digitLists[i].begin(), digitLists[i].end());
    }
    counterX2 = -1;
    traverse(0, 0);
    cout << totalAnswer << '\n';
    return 0;
}
